var<workgroup> tile: array<u32, 64>;

@group(0) @binding(0) var<uniform> args: Args;
@group(0) @binding(1) var<storage, read> src: array<u32>;
@group(0) @binding(2) var<storage, read_write> out: array<u32>;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) gid: vec3<u32>, @builtin(local_invocation_id) lid: vec3<u32>, @builtin(workgroup_id) wid: vec3<u32>) {
  tile[lid.x] = src[gid.x];
  workgroupBarrier();
  for (var stride: u32 = 32u; (stride > 0u); stride /= 2u) {
    if ((lid.x < stride)) {
      tile[lid.x] += tile[lid.x + stride];
    }
    workgroupBarrier();
  }
  if ((lid.x == 0u)) {
    out[wid.x] = tile[0];
  }
}

